export function generateRelease({ version, sourceRevision }) {
  if (typeof version !== 'string' || version.trim().length === 0) {
    throw new TypeError('version must be a nonblank string');
  }
  if (typeof sourceRevision !== 'string' || !/^[a-f0-9]{40}$/.test(sourceRevision) || sourceRevision.length !== 40) {
    throw new TypeError('sourceRevision must be exactly 40 lowercase hexadecimal characters');
  }
  return { version, sourceRevision };
}
